SELECT 
FROM openplat_api_config a
LEFT JOIN openplat_system s ON a.system_id = s.id


        AND a.api_code LIKE CONCAT('%', #{apiCode}, '%')


        AND a.api_name LIKE CONCAT('%', #{apiName}, '%')


        AND a.api_path LIKE CONCAT('%', #{apiPath}, '%')


        AND a.api_method = #{apiMethod}


        AND a.system_id = #{systemId}


        AND a.status = #{status}


ORDER BY a.create_time DESC

